def randomise(self, value):
    self._check_all(value)

    if self._scale == 0:
        return value

    tau = 1 / (1 + np.floor(self._scale))
    sigma2 = self._scale ** 2

    while True:
        geom_x = 0
        while bernoulli_neg_exp(tau, self._rng):
            geom_x += 1

        bern_b = self._rng.random() < 0.5
        if bern_b and not geom_x:
            continue

        lap_y = int((1 - 2 * bern_b) * geom_x)
        bern_c = bernoulli_neg_exp((abs(lap_y) - tau * sigma2) ** 2 / 2 / sigma2, self._rng)
        if bern_c:
            return value + lap_y

def _check_utility_candidates_measure(cls, utility, candidates, measure):
    if not isinstance(utility, list):
        raise TypeError(f"Utility must be a list, got a {utility}.")

