def __init__(self, *, epsilon, sensitivity, gamma=None, random_state=None):
    super().__init__(epsilon=epsilon, delta=0, sensitivity=sensitivity, random_state=random_state)
    self.gamma = self._check_gamma(gamma, epsilon=self.epsilon)

    if isinstance(self._rng, secrets.SystemRandom):
        self._rng = np.random.default_rng()

def _check_gamma(cls, gamma, epsilon=None):
    if gamma is None and epsilon is not None:
        gamma = 1 / (1 + np.exp(epsilon / 2))

    if not isinstance(gamma, Real):
        raise TypeError("Gamma must be numeric")
    if not 0.0 <= gamma <= 1.0:
        raise ValueError("Gamma must be in [0,1]")

    return float(gamma)

def __init__(self, *, epsilon, delta, sensitivity, random_state=None):
    super().__init__(epsilon=epsilon, delta=delta, sensitivity=sensitivity, random_state=random_state)
    self._scale = self._find_scale()

def _find_scale(self):
    if self.sensitivity / self.epsilon == 0:
        return 0.0

    epsilon = self.epsilon
    delta = self.delta

    def phi(val):
        return (1 + erf(val / np.sqrt(2))) / 2

    def b_plus(val):
        return phi(np.sqrt(epsilon * val)) - np.exp(epsilon) * phi(- np.sqrt(epsilon * (val + 2))) - delta

    def b_minus(val):
        return phi(- np.sqrt(epsilon * val)) - np.exp(epsilon) * phi(- np.sqrt(epsilon * (val + 2))) - delta

    delta_0 = b_plus(0)

    if delta_0 < 0:
        target_func = b_plus
    else:
        target_func = b_minus

    # Find the starting interval by doubling the initial size until the target_func sign changes, as suggested
    # in the paper
    left = 0
    right = 1

    while target_func(left) * target_func(right) > 0:
        left = right
        right *= 2

    # Binary search code copied from mechanisms.LaplaceBoundedDomain
    old_interval_size = (right - left) * 2

    while old_interval_size > right - left:
        old_interval_size = right - left
        middle = (right + left) / 2

        if target_func(middle) * target_func(left) <= 0:
            right = middle
        if target_func(middle) * target_func(right) <= 0:
            left = middle

    alpha = np.sqrt(1 + (left + right) / 4) + (-1 if delta_0 < 0 else 1) * np.sqrt((left + right) / 4)

    return alpha * self.sensitivity / np.sqrt(2 * self.epsilon)

def apply(self, X):
    """Finds the terminal region (=leaf node) for each sample in X."""
    n_samples = X.shape[0]
    out = np.zeros((n_samples,), dtype=int)
    out_ptr = out.data

    for i in range(n_samples):
        node = self.nodes[0]

        while node.left_child != self._TREE_LEAF:
            if X[i, node.feature] <= node.threshold:
                node = self.nodes[node.left_child]
            else:
                node = self.nodes[node.right_child]

        out_ptr[i] = node.node_id

    return out

def get_max_sensitivity(y_lower, y_upper, x_lower, x_upper):
    corners = [y_lower * x_lower, y_lower * x_upper, y_upper * x_lower, y_upper * x_upper]
    return np.max(corners) - np.min(corners)

def obj(idx):
